"""Generate the static SEO head block and the no-JavaScript fallback from data/site.json.

Used by tools/sync_head.py (writes index.html) and tools/check_site.py (verifies it is in sync).
Standard library only.
"""
import html
import json
import pathlib
from urllib.parse import urljoin

ROOT = pathlib.Path(__file__).resolve().parent.parent
DATA = ROOT / "data" / "site.json"
INDEX = ROOT / "index.html"
MARKERS = {
    "SEO": ("<!-- SEO:START (generated by tools/sync_head.py from data/site.json, do not edit by hand) -->",
            "<!-- SEO:END -->"),
    "NOSCRIPT": ("<!-- NOSCRIPT:START -->", "<!-- NOSCRIPT:END -->"),
}
SCHEMA_DAYS = {"Mo": "Monday", "Tu": "Tuesday", "We": "Wednesday", "Th": "Thursday",
               "Fr": "Friday", "Sa": "Saturday", "Su": "Sunday"}


def load():
    return json.loads(DATA.read_text(encoding="utf-8"))


def is_todo(data, value):
    m = data["todo_marker"]
    if value in (None, "", m):
        return True
    if isinstance(value, list):
        return not value or m in value
    return False


def site_url(data):
    u = data["pharmacy"]["site_url"]
    return None if is_todo(data, u) else u.rstrip("/") + "/"


def json_ld(data):
    ph = data["pharmacy"]
    ld = {
        "@context": "https://schema.org",
        "@type": "Pharmacy",
        "name": ph["name_ar"],
        "alternateName": ph["name_en"],
        "telephone": ph["mobile_e164"],
        "address": {
            "@type": "PostalAddress",
            "addressLocality": ph["locality_en"],
            "addressRegion": ph["region_en"],
            "addressCountry": ph["country_code"],
        },
        "hasMap": ph["maps_link"],
        "contactPoint": [{
            "@type": "ContactPoint",
            "contactType": "customer service",
            "telephone": ph["mobile_e164"],
            "url": ph["whatsapp_link"],
            "availableLanguage": ["ar", "en"],
        }],
    }
    base = site_url(data)
    if base:
        ld["url"] = base
    if not is_todo(data, ph["logo"]):
        ld["logo"] = ld["image"] = urljoin(base, ph["logo"]) if base else ph["logo"]
    social = [v for v in ph["social"].values() if not is_todo(data, v)]
    if social:
        ld["sameAs"] = social
    if not is_todo(data, data["hours"]):
        ld["openingHoursSpecification"] = [{
            "@type": "OpeningHoursSpecification",
            "dayOfWeek": [SCHEMA_DAYS[d] for d in h["days"]],
            "opens": h["opens"],
            "closes": h["closes"],
        } for h in data["hours"]]
    return ld


def seo_block(data):
    ar = data["strings"]["ar"]
    e = html.escape
    lines = [
        f"<title>{e(ar['meta.title'])}</title>",
        f'<meta name="description" content="{e(ar["meta.description"])}">',
        '<meta property="og:type" content="website">',
        f'<meta property="og:site_name" content="{e(data["pharmacy"]["name_ar"])}">',
        f'<meta property="og:title" content="{e(ar["meta.title"])}">',
        f'<meta property="og:description" content="{e(ar["meta.description"])}">',
        '<meta property="og:locale" content="ar_EG">',
        '<meta property="og:locale:alternate" content="en_US">',
    ]
    base = site_url(data)
    if base:
        lines.append(f'<meta property="og:url" content="{e(base)}">')
        lines.append(f'<link rel="canonical" href="{e(base)}">')
    logo = data["pharmacy"]["logo"]
    if base and not is_todo(data, logo):
        lines.append(f'<meta property="og:image" content="{e(urljoin(base, logo))}">')
    ld = json.dumps(json_ld(data), ensure_ascii=False, indent=1).replace("</", "<\\/")
    lines.append('<script type="application/ld+json" id="ld">\n' + ld + "\n</script>")
    return "\n".join(lines)


def noscript_block(data):
    ph = data["pharmacy"]
    ar = data["strings"]["ar"]
    e = html.escape
    return (
        '<noscript><div class="nojs">'
        f"<p><strong>{e(ph['name_ar'])}</strong> · {e(ph['city_ar'])}</p>"
        f'<p><a href="{e(ph["whatsapp_link"])}">{e(ar["hero.order"])}: {e(ph["whatsapp_display"])}</a></p>'
        f'<p><a href="{e(ph["maps_link"])}">{e(ar["location.open_map"])}</a></p>'
        "</div></noscript>"
    )


def render_index(text, data):
    blocks = {"SEO": seo_block(data), "NOSCRIPT": noscript_block(data)}
    for name, (start, end) in MARKERS.items():
        i, j = text.index(start), text.index(end)
        text = text[: i + len(start)] + "\n" + blocks[name] + "\n" + text[j:]
    return text
